<?php
declare(strict_types=1);
require_once __DIR__.'/../src/account_helpers.php';
require_once __DIR__.'/../src/audience_ai.php';
$checks=0;
$expect=static function(bool $ok,string $message)use(&$checks):void{if(!$ok)throw new RuntimeException($message);$checks++;};
$reject=static function(callable $call,string $message)use($expect):void{try{$call();}catch(Throwable){$expect(true,$message);return;}$expect(false,$message);};
$fact=static fn(string $id,string $entity,float|int|null $value,?float $previous=null,string $metric='click_rate',string $unit='%'):array=>[
    'id'=>$id,'label'=>$entity.' · '.($metric==='click_rate'?'Click rate':$metric),'value'=>$value,'previous'=>$previous,'change'=>null,'unit'=>$unit,
    'measurement'=>['metric'=>$metric,'label'=>$metric==='click_rate'?'Click rate':$metric,'entity'=>$entity,'family'=>'population:'.$metric,'scope'=>'2026-09-01 to 2026-09-30 UTC'],
];
$evidence=['facts'=>[$fact('overall','Selected period overall',13.64),$fact('a','Newsletter',18.18),$fact('b','Invitation',9.09),$fact('c','Third campaign',9.09),$fact('bounce','Newsletter',8.33,null,'bounce_rate')],'tables'=>[],'limitations'=>['Industry benchmarks are unavailable.']];
$calculate=static fn(array $ids,string $operation='compare',?array $data=null)=>audienceAiCalculateFinding(['operation'=>$operation,'evidence_ids'=>$ids],$data??$evidence);
$pair=$calculate(['b','a']);
$expect($pair['text']==='Click rate: Newsletter (18.18%) is higher than Invitation (9.09%) by 9.09 percentage points.','Order comes from the values, and percentage points are not relative percent change.');
$expect($pair['evidence_ids']===['b','a'],'Both compared source cards remain cited.');
$rank=$calculate(['overall','b','a']);
$expect($rank['text']==='Click rate, highest to lowest among these results: Newsletter (18.18%); Selected period overall (13.64%); Invitation (9.09%).','The formerly false lower-than-both claim is replaced by the correct computed ranking.');
$expect($calculate(['a','b','overall'])['text']===$rank['text'],'Ranking does not depend on model selection order.');
$expect(str_contains($calculate(['b','c'])['text'],'are equal at 9.09%'),'Equal values produce equality, not an invented winner.');
$expect(str_contains($calculate(['c','a','b'])['text'],'Invitation and Third campaign (9.09% each; tied)'),'Rankings preserve ties without implying a global rank outside the selected results.');
$reject(static fn()=>$calculate(['a','bounce']),'Metrics with identical units cannot be compared as if they measure the same thing.');
$mismatched=$evidence;$mismatched['facts'][2]['measurement']['family']='different population';
$reject(static fn()=>$calculate(['a','b'],'compare',$mismatched),'A different segment or campaign population cannot silently supply a baseline.');
$mismatched=$evidence;$mismatched['facts'][2]['unit']='count';
$reject(static fn()=>$calculate(['a','b'],'compare',$mismatched),'Unit mismatches are rejected.');
foreach([['missing','a'],['a','a'],['a'],[['a'],'b']]as$ids)$reject(static fn()=>$calculate($ids),'Invalid source selections cannot become a comparison.');
$reject(static fn()=>audienceAiCalculateFinding(['operation'=>'compare','evidence_ids'=>['a','b'],'direction'=>'lower'],$evidence),'The model cannot override a computed relation.');
$nulls=['facts'=>[$fact('a','Newsletter',null),$fact('b','Invitation',0)]];
$text=$calculate(['a','b'],'compare',$nulls)['text'];
$expect(str_contains($text,'insufficient recorded values')&&str_contains($text,'Invitation: 0%')&&str_contains($text,'Newsletter: Click rate is unavailable.'),'Missing data and a true zero have different meanings.');
$expect(str_contains($calculate(['a'],'previous')['text'],'previous-period comparison is unavailable'),'Missing previous values never become zero.');
$zero=['facts'=>[$fact('a','Newsletter',5,0)]];
$text=$calculate(['a'],'previous',$zero)['text'];
$expect(str_contains($text,'increased from 0% to 5% (5 percentage points)')&&str_contains($text,'baseline is zero'),'Zero baseline permits an absolute difference but never a relative percentage.');
$negative=['facts'=>[$fact('a','Source A',-2,-10,'net','count'),$fact('b','Source B',-6,null,'net','count')]];
$expect(str_contains($calculate(['a','b'],'compare',$negative)['text'],'Source A (-2) is higher than Source B (-6) by 4'),'Signed values retain their meaning in comparisons.');
$text=$calculate(['a'],'previous',$negative)['text'];
$expect(str_contains($text,'increased from -10 to -2 (8)')&&str_contains($text,'Relative change: 80%'),'Relative change uses the absolute baseline for negative values.');
$previous=['facts'=>[$fact('a','Newsletter',4,8),$fact('b','Invitation',8.33,8.33)]];
$expect(str_contains($calculate(['a'],'previous',$previous)['text'],'decreased from 8% to 4% (4 percentage points). Relative change: -50%.'),'Direction, percentage points and relative change are computed independently.');
$expect(str_contains($calculate(['b'],'previous',$previous)['text'],'unchanged at 8.33%'),'Equal periods remain unchanged.');
$catalog=audienceAiFindingCatalog($previous);
$expect(isset($catalog['previous:b'])&&!isset($catalog['value:b']),'Selecting a measurement with a known baseline cannot omit its unchanged comparison.');
$precision=['facts'=>[$fact('a','A',1.004),$fact('b','B',1.003)]];
$expect(str_contains($calculate(['a','b'],'compare',$precision)['text'],'are equal at 1%'),'Comparison precision matches the displayed cards.');
$precision['facts'][1]['value']=1.005;
$expect(str_contains($calculate(['a','b'],'compare',$precision)['text'],'by 0.01 percentage points'),'Differences use displayed precision consistently, never higher by zero.');
$scoped=$evidence;$scoped['facts'][2]['measurement']['scope']='2026-08-01 to 2026-08-31 UTC';
$expect(str_contains($calculate(['a','b'],'compare',$scoped)['text'],'2026-08-01 to 2026-08-31 UTC'),'Comparisons across report windows identify both scopes.');
$request=['mode'=>'analytics','operation'=>'analyze','prompt'=>'Compare these reports.','evidence'=>$evidence];
$followup=$request;$followup['prompt']='And their open rates?';$followup['previous_context']=['question'=>'Compare the most recent campaigns.','summary'=>'A comparison of the selected campaigns.','queries'=>[]];
$messages=audienceAiFindingPayload($followup)['messages'];
$expect(array_slice(array_column($messages,'role'),-3)===['user','assistant','user']&&str_contains($messages[count($messages)-3]['content'],'Compare')&&end($messages)['content']===$followup['prompt'],'Finding selection keeps the original comparison intent and the latest metric follow-up in speaker order.');
$raw=static fn($value)=>['done'=>true,'done_reason'=>'stop','message'=>['content'=>json_encode($value)]];
$request['evidence']['facts']=array_slice($evidence['facts'],0,3);
$plan=['finding_ids'=>['compare:overall:member'],'limitation_ids'=>[],'recommendations'=>[]];
$reply=audienceAiReply($raw($plan),$request);
$expect($reply['interpretation']==='calculated'&&$reply['observations'][0]['text']===$rank['text'],'The actual reply path uses the deterministic comparator.');
$falseProse=['summary'=>'The selected period click rate (13.64%) is lower than both campaigns (18.18% and 9.09%).','observations'=>[],'recommendations'=>[]];
$reject(static fn()=>audienceAiReply($raw($falseProse),$request),'The original false statement fails even though every number exists in evidence.');
$reject(static fn()=>audienceAiReply($raw($plan+$falseProse),$request),'A valid comparison plan cannot smuggle in a contradictory summary.');
$payload=audienceAiPayload($request);
$expect(isset($payload['format']['properties']['finding_ids'])&&!isset($payload['format']['properties']['summary']),'Report generation requests reference selections, not unverified factual prose.');
$expect($payload['options']['num_predict']<=1100&&$payload['think']===false,'The structured report path stays within the existing inference budget.');
$plan['limitation_ids']=['limitation_0'];
$expect(audienceAiReply($raw($plan),$request)['summary']===$evidence['limitations'][0],'Limitations come from the retrieved evidence, not invented benchmarks.');
$plan['limitation_ids']=['limitation_99'];
$reject(static fn()=>audienceAiReply($raw($plan),$request),'Unavailable limitation references are rejected.');
$grouped=$evidence;$grouped['facts'][0]['measurement']['level']='total';$grouped['facts'][]=$fact('bounce2','Invitation',8.33,null,'bounce_rate');
$catalog=audienceAiFindingCatalog($grouped);
$expect($catalog['compare:a:member']['evidence_ids']===['a','b','c']&&!str_contains($catalog['compare:a:member']['text'],'Selected period overall'),'The catalog distinguishes campaign peers from an aggregate.');
$expect($catalog['compare:bounce:member']['evidence_ids']===['bounce','bounce2'],'Separate metrics receive separate computed choices.');
$plan=['finding_ids'=>['compare:bounce:member','compare:bounce:member'],'limitation_ids'=>[],'recommendations'=>[]];
$expect(count(audienceAiFindingReply($plan,['evidence'=>$grouped])['observations'])===1,'Repeated selections cannot duplicate the same finding.');
$plan['finding_ids']=['invented'];$reject(static fn()=>audienceAiFindingReply($plan,['evidence'=>$grouped]),'Only application-calculated choices can be displayed as report findings.');
echo "Audience AI calculated findings passed ($checks checks).\n";
